	Product       int
	Factorizations [][2]int
}

// Products returns the smallest and largest palindromic products
// of two numbers within the inclusive range [fmin, fmax], along
// with all factor pairs of each within that range.
//
// It returns an error if fmin > fmax or if no palindromic products
// exist within the range.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var minP, maxP Product
	minFound, maxFound := false, false

	for a := fmin; a <= fmax; a++ {
		for b := a; b <= fmax; b++ {
			p := a * b
			if !isPalindrome(p) {
				continue
			}
			if !minFound || p < minP.Product {
				minP = Product{Product: p, Factorizations: [][2]int{{a, b}}}
				minFound = true
			} else if p == minP.Product {
				minP.Factorizations = append(minP.Factorizations, [2]int{a, b})
			}
			if !maxFound || p > maxP.Product {
				maxP = Product{Product: p, Factorizations: [][2]int{{a, b}}}
				maxFound = true
			} else if p == maxP.Product {
				maxP.Factorizations = append(maxP.Factorizations, [2]int{a, b})
			}
		}
	}

	if !minFound || !maxFound {
		return Product{}, Product{}, errors.New("no palindromes found")
	}

	return minP, maxP, nil
}

// isPalindrome reports whether the decimal digits of n read the same
// forwards and backwards. Negative numbers are not palindromes.
func isPalindrome(n int) bool {
	if n < 0 {
		return false
	}
	s := strconv.Itoa(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}
